const img = document.getElementById('product-img');
const video = document.getElementById('product-video');
const canvas = document.getElementById('waveform-canvas');
const pictureImg = document.getElementById('picture-img');
const iframe = document.getElementById('product-iframe');
const banner = document.getElementById('hero-banner');
const swatchRed = document.getElementById('swatch-red');
const nestedImg = document.getElementById('nested-img');
const nestedContainer = document.getElementById('nested-container');

if (!img || !video || !canvas || !pictureImg || !iframe || !banner || !swatchRed || !nestedImg || !nestedContainer) {
  return false;
}

if (!document.getElementById('ai4a11y-dark-mode')) {
  return true;
}

const htmlStyle = window.getComputedStyle(document.documentElement);
const htmlDarkFilter = htmlStyle.getPropertyValue('--ai4a11y-filter-dark').trim();
if (!htmlDarkFilter.includes('invert(90%)') || !htmlDarkFilter.includes('hue-rotate(180deg)')) {
  return false;
}

const imgStyle = window.getComputedStyle(img);
const imgMediaDark = imgStyle.getPropertyValue('--ai4a11y-media-dark').trim();
if (!imgMediaDark.includes('invert(100%)') || !imgMediaDark.includes('hue-rotate(180deg)')) {
  return false;
}

const swatchStyle = window.getComputedStyle(swatchRed);
const swatchMediaDark = swatchStyle.getPropertyValue('--ai4a11y-media-dark').trim();
if (!swatchMediaDark.includes('invert(100%)')) {
  return false;
}

const nestedStyle = window.getComputedStyle(nestedImg);
const nestedMediaDark = nestedStyle.getPropertyValue('--ai4a11y-media-dark').trim();
if (nestedMediaDark !== 'initial' && nestedMediaDark !== '') {
  return false;
}

return true;

const buyBtn = document.getElementById('buy-button');
const couponInput = document.getElementById('coupon-code');
const applyBtn = document.getElementById('apply-coupon');
const navHeadphones = document.getElementById('nav-headphones');
if (!buyBtn || !couponInput || !applyBtn || !navHeadphones) return false;

couponInput.focus();
if (document.activeElement !== couponInput) return false;
couponInput.value = 'STUDIO20';
couponInput.dispatchEvent(new Event('input', { bubbles: true }));
if (couponInput.value !== 'STUDIO20') return false;
couponInput.value = '';
couponInput.blur();

const adapter = window.__ai4a11yDarkMode;
if (!adapter || !adapter.enabled) return true;

adapter.enable();
const styles = document.querySelectorAll('#ai4a11y-dark-mode');
if (styles.length !== 1) return false;

adapter.toggle();
if (adapter.enabled !== false || document.getElementById('ai4a11y-dark-mode')) return false;

adapter.toggle();
if (adapter.enabled !== true || !document.getElementById('ai4a11y-dark-mode')) return false;

return true;

const buyBtn = document.getElementById('buy-button');
const swatchRed = document.getElementById('swatch-red');
const navLink = document.getElementById('nav-headphones');
const skipLink = document.querySelector('.skip-link');
const couponInput = document.getElementById('coupon-code');
if (!buyBtn || !swatchRed || !navLink || !skipLink || !couponInput) return false;

const buyRect = buyBtn.getBoundingClientRect();
const swatchRect = swatchRed.getBoundingClientRect();
const navRect = navLink.getBoundingClientRect();
const inputRect = couponInput.getBoundingClientRect();

if (buyRect.width < 24 || buyRect.height < 24) return false;
if (swatchRect.width < 24 || swatchRect.height < 24) return false;
if (navRect.width < 24 || navRect.height < 24) return false;
if (inputRect.width < 24 || inputRect.height < 24) return false;

if (!buyBtn.textContent.includes('Add to Cart')) return false;
if (swatchRed.getAttribute('aria-label') !== 'Crimson Red') return false;

buyBtn.focus();
if (document.activeElement !== buyBtn) return false;
let cs = window.getComputedStyle(buyBtn);
if (parseFloat(cs.outlineWidth) < 2) return false;

const pt = document.elementFromPoint(buyRect.left + buyRect.width / 2, buyRect.top + buyRect.height / 2);
if (!buyBtn.contains(pt)) return false;

buyBtn.blur();
return true;

