const title = document.getElementById('product-title');
const price = document.getElementById('product-price');
const cartIcon = document.getElementById('cart-icon');
const aside = document.querySelector('aside');
const footer = document.querySelector('footer');

if (!h1 || !title || !price || !cartIcon || !aside || !footer) return false;

if (!h1.textContent.includes('Aura Sound Lab')) return false;
if (!title.textContent.includes('Aura Studio Pro Wireless')) return false;
if (!price.textContent.includes('$349.00')) return false;

const iconStyle = window.getComputedStyle(cartIcon);
const iconMediaDark = iconStyle.getPropertyValue('--ai4a11y-media-dark').trim();
if (iconMediaDark.includes('invert(100%)')) return false;

return true;
